#!/usr/bin/env python3
"""Generate dp_ingest batch SQL (batch + rows) for NDA 2026-II GAT GK Q51-150 from the staged JSON.
Usage: python3 gen_nda_ii_2026_gk_batch_sql.py [--fidelity 0.97] > out.sql   (does not touch any DB)
Raise --fidelity to 0.99 only after the visual source-QA pass against the scan is complete."""
import json, hashlib, re, sys, argparse
ap=argparse.ArgumentParser(); ap.add_argument('--fidelity',type=float,default=0.97); a=ap.parse_args()
rows=json.load(open(__file__.rsplit('/',1)[0]+'/nda_ii_2026_gat_gk_staged.json'))
NEG={94,99,100,119,136,143}
def norm(s): return re.sub(r'\s+',' ',s).strip().lower()
def comp(subj,topic):
    if subj=='Science & Technology': return {'Physics':'COMP.SNT.PHYSICS','Chemistry':'COMP.SNT.CHEMISTRY'}.get(topic,'COMP.SNT.BIOLOGY')
    if subj=='Geography': return {'Physical Geography':'COMP.GEOGRAPHY.PHYSICAL','Indian Geography':'COMP.GEOGRAPHY.INDIA','Human Geography':'COMP.GEOGRAPHY.HUMAN'}.get(topic,'COMP.GEOGRAPHY.SPATIAL' if topic=='World Geography' else 'COMP.GEOGRAPHY.HUMAN')
    if subj=='History': return {'Modern History':'COMP.HISTORY.MOVEMENTS','World History':'COMP.HISTORY.ECONOMIC','Art & Culture':'COMP.HISTORY.CULTURE'}.get(topic,'COMP.HISTORY.INSTITUTIONS')
    if subj=='Polity': return {'Constitutional Framework':'COMP.POLITY.CONSTITUTION','Federalism':'COMP.POLITY.FEDERALISM','Judiciary':'COMP.POLITY.JUDICIARY'}.get(topic,'COMP.POLITY.GOVERNANCE')
    if subj=='Economy': return 'COMP.ECONOMY.DEVELOPMENT' if topic=='Development & Welfare' else 'COMP.ECONOMY.MACRO'
    if subj=='International Relations': return 'COMP.IR.INSTITUTIONS'
    if subj=='Current Affairs':
        if topic=='Defence & Security': return 'COMP.SECURITY.OPERATIONS'
        if topic=='International Relations': return 'COMP.IR.BILATERAL'
        if topic=='Environment & Ecology': return 'COMP.ENVIRONMENT.BIODIVERSITY'
        if topic in('Science & Technology',): return 'COMP.CA.SCIENCE'
        if topic in('Sports','Awards, Appointments & Personalities'): return 'COMP.CA.EVENTS'
        return 'COMP.CA.POLICY'
    raise SystemExit('no competency for '+subj)
SRC={'Science & Technology':'SRC.NCERT.SCIENCE','Geography':'SRC.NCERT.GEOGRAPHY','History':'SRC.NCERT.HISTORY','Polity':'SRC.LAXMIKANTH','Economy':'SRC.NCERT.ECONOMICS','International Relations':'SRC.OTHER_REFERENCE','Current Affairs':'SRC.PIB'}
CAT={'E':('Easy',20),'M':('Moderate',42.25),'H':('Hard',62)}
def q(s): return "$q$"+s+"$q$" if s is not None else 'null'
out=["begin;",
"insert into dp_ingest.batches(batch_code,exam,year,cycle,paper,expected_question_count,source_question_url,source_version,status,key_policy,key_policy_approved_by,key_policy_approved_at,key_policy_note,notes)",
"values('NDA_2026_II_GAT_GK_SET_A','NDA',2026,'II','General Ability Test',100,'upload:NDA-2-2026-GAT-Question-Paper-NCA.pdf','scan-transcription-v1','ENRICHED','FOUNDER_APPROVED_SOLVED','founder (approval to be recorded at apply time)',null,",
"$q$GAT Part B (General Knowledge) Q51-150 of NDA II 2026, booklet series A (TFDD-B-AGT - A), English side only. Keys solved by Claude using the scan, open sources and reasoning; not an official UPSC key. Medium-confidence keys: 57 67 69 87 90 91 102 127 142 143 146 148.$q$,",
"$q$Staged only, not promoted. Generated by gen_nda_ii_2026_gk_batch_sql.py.$q$);"]
out.append("with b as (select id from dp_ingest.batches where batch_code='NDA_2026_II_GAT_GK_SET_A')")
out.append("insert into dp_ingest.rows(batch_id,q_num,source_page,raw_question,raw_opt_a,raw_opt_b,raw_opt_c,raw_opt_d,extraction_confidence,extraction_flags,question_id,question,opt_a,opt_b,opt_c,opt_d,content_hash,source_key_opt,key_authority,key_source_url,official_opt,llm_opt,final_opt,key_discrepancy,subject,topic,subtopic,theme,q_type,q_pattern,pattern_id,explanation,source,is_negative,tags,static_current_link,difficulty_score,difficulty_category,source_fidelity_confidence,taxonomy_confidence,intelligence_confidence,review_required,row_status,release_disposition,taxonomy_concept,competency_id,source_id,temporal_context_id,expected_knowledge,source_accessibility,preparation_accessibility,cognitive_complexity,esac_score,relation_degree,same_concept_degree,cross_exam_variant_degree,conceptual_variant_degree,model_audit)")
PID={'Single MCQ':'PATTERN.DIRECT','2-Statement Combination':'PATTERN.STATEMENT.2','3-Statement Combination':'PATTERN.STATEMENT.3','4-Statement Combination':'PATTERN.STATEMENT.4','Statement Count':'PATTERN.COUNT','Match the Following':'PATTERN.MATCHING','Ordering/Sequence':'PATTERN.ORDERING','Chronology':'PATTERN.CHRONOLOGY','Assertion-Reason':'PATTERN.ASSERTION_REASON'}
vals=[]
for r in rows:
    o=[r['options'][k] for k in 'ABCD']; cat,sc=CAT[r['difficulty']]
    h=hashlib.sha256(json.dumps([norm(r['question_text']),sorted(map(norm,o))]).encode()).hexdigest()
    cur=r['subject']=='Current Affairs'
    audit=json.dumps({"answer_audit":{"authority":"DP_SOLVED_INTERNAL","note":"Not an official UPSC key"},"source_explanation_evidence":{"captured":True,"provider":"DP internal solved key","text":r['explanation']}})
    vals.append("select b.id,%d,null,%s,%s,%s,%s,%s,0.98,'{}'::text[],%s,%s,%s,%s,%s,%s,%s,%s,'MODEL_ONLY',%s,null,%s,%s,false,%s,%s,%s,%s,'Knowledge',%s,%s,%s,%s,%s,array['format:single_mcq','key:dp_solved'],%s,%s,%s,%s,0.85,0.85,false,'ENRICHED','INCLUDE',%s,%s,%s,%s,80,%s,100,60,%s,0,0,0,0,%s::jsonb from b"%(
      r['q_num'],q(r['question_text']),q(o[0]),q(o[1]),q(o[2]),q(o[3]),
      q(r['question_id']),q(r['question_text']),q(o[0]),q(o[1]),q(o[2]),q(o[3]),q(h),q(r['answer']),
      q('dp-solved://NDA_2026_II_GAT_GK_SET_A'),q(r['answer']),q(r['answer']),
      q(r['subject']),q(r['topic']),q(r['subtopic']),q(r['theme']),q(r['q_pattern']),q(PID[r['q_pattern']]),q(r['explanation']),
      q('NDA II 2026 General Ability Test Part B (English side)'),'true' if r['q_num'] in NEG else 'false',
      q('Current Affairs' if cur else 'Static'),sc,q(cat),a.fidelity,
      q(r['theme']),q(comp(r['subject'],r['topic'])),q(SRC[r['subject']]),q('TEMP.CURRENT_DEVELOPMENT' if cur else 'TEMP.STATIC'),
      '70' if cur else '90', repr(round(100-sc,2)), q(audit)))
out.append("\nunion all\n".join(vals)+";")
out.append("commit;")
print("\n".join(out))
